<?php
ini_set('display_errors','0');header('Content-Type: application/json;charset=utf-8');require __DIR__.'/../lib/Db.php';require __DIR__.'/../lib/Jwt.php';$C=require __DIR__.'/../config.php';date_default_timezone_set('Asia/Tehran');$h=$_SERVER['HTTP_AUTHORIZATION']??'';if(!preg_match('/Bearer\s+(.+)/i',$h,$m)){http_response_code(401);exit;}if(!Jwt::verify(trim($m[1]),$C['jwt_secret'])){http_response_code(401);exit;}function j($x){echo json_encode($x,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}function url($p){return $p?'https://app.yousefipour.ir/station-image-v3.php?path='.rawurlencode($p):null;}$op=$_GET['op']??'map';if($op==='map'){$rows=Db::all("SELECT l.id,l.code,l.origin,l.destination,l.status,l.latitude,l.longitude,l.location_updated_at,s.id station_id,s.station_status,s.accuracy_m,s.physical_address,s.location_photo_path,s.captured_at FROM `lines` l LEFT JOIN line_station_locations s ON s.id=l.station_location_id ORDER BY l.code");foreach($rows as &$r){$r['registered']=!!$r['station_id'];$r['location_photo_url']=url($r['location_photo_path']);$r['signs']=$r['station_id']?Db::all('SELECT z.id,t.title,z.photo_path FROM line_station_signs z JOIN station_sign_types t ON t.id=z.sign_type_id WHERE z.station_location_id=? ORDER BY z.id',[$r['station_id']]):[];foreach($r['signs'] as &$z)$z['photo_url']=url($z['photo_path']);unset($z);}$stats=['total'=>count($rows),'registered'=>count(array_filter($rows,fn($x)=>$x['registered']))];j(['stats'=>$stats,'lines'=>$rows]);}j(['error'=>'عملیات نامعتبر است']);